<template><div class="slide-up pb-8"><StepHeader :step="3" eyebrow="Ткань и дизайн" title="Собери характер" description="Выбери материал и добавь готовый или свой дизайн." /><h2 class="mb-3 text-lg font-bold">Ткань</h2><div class="space-y-3"><OptionCard v-for="fabric in FABRICS" :key="fabric.id" :title="fabric.name" :description="fabric.description" :price="fabric.additionalPrice" :selected="order.draft.fabric?.id === fabric.id" @select="order.setFabric(fabric)" /></div><h2 class="mb-3 mt-8 text-lg font-bold">Дизайн</h2><div class="grid grid-cols-3 gap-3"><button v-for="design in EXISTING_DESIGNS" :key="design.id" class="rounded-2xl border bg-white p-3 text-left transition" :class="selectedExisting === design.id ? 'border-sage ring-2 ring-sage/10' : 'border-line'" @click="selectExisting(design)"><span class="mb-3 block aspect-square rounded-xl" :style="{ background: design.accent }"><span class="flex h-full items-center justify-center text-xs font-bold text-ink/50">CF</span></span><span class="text-xs font-bold">{{ design.name }}</span></button></div><label class="mt-4 block cursor-pointer rounded-2xl border border-dashed border-sage bg-mint p-4"><span class="text-sm font-bold text-sage">Загрузить свой дизайн</span><span class="mt-1 block text-xs text-ink/50">JPG, PNG, WEBP до 5 МБ</span><input class="hidden" type="file" accept="image/jpeg,image/png,image/webp" @change="handleFile"></label><div v-if="previewUrl" class="relative mt-3 overflow-hidden rounded-2xl bg-white"><img :src="previewUrl" alt="Предпросмотр дизайна" class="max-h-48 w-full object-contain" /><button class="absolute right-2 top-2 rounded-full bg-ink px-3 py-1 text-xs font-bold text-white" @click="removeUpload">Удалить</button></div><p v-if="error" class="mt-3 text-sm text-terracotta">{{ error }}</p><BackNext back-to="/preview" :disabled="!order.draft.fabric || !order.draft.design" @next="goNext" /></div></template>
<script setup lang="ts">import { EXISTING_DESIGNS, FABRICS } from '~/config/catalog'; import type { Design } from '~/types/order'; const order = useOrderStore(); const error = ref(''); const previewUrl = ref(order.draft.design?.uploadedImageUrl ?? ''); const selectedExisting = computed(() => order.draft.design?.existingDesignId ?? ''); function selectExisting(design: { id: string; name: string }): void { previewUrl.value = ''; order.setDesign({ type: 'existing', existingDesignId: design.id, existingDesignName: design.name, uploadedImageUrl: null, uploadedImageName: null, additionalPrice: 0 }) } function handleFile(event: Event): void { const input = event.target as HTMLInputElement; const file = input.files?.[0]; if (!file) return; if (file.size > 5 * 1024 * 1024) { error.value = 'Файл слишком большой. Максимальный размер — 5 МБ.'; return } previewUrl.value = URL.createObjectURL(file); const design: Design = { type: 'uploaded', existingDesignId: null, existingDesignName: null, uploadedImageUrl: previewUrl.value, uploadedImageName: file.name, additionalPrice: 0 }; order.setDesign(design); error.value = '' } function removeUpload(): void { previewUrl.value = ''; order.setDesign({ type: 'existing', existingDesignId: null, existingDesignName: null, uploadedImageUrl: null, uploadedImageName: null, additionalPrice: 0 }) } function goNext(): void { if (!order.draft.fabric) { error.value = 'Выберите ткань'; return } if (!order.draft.design) { error.value = 'Выберите дизайн или загрузите свой'; return } navigateTo('/measurements') }</script>
